"""Helpers for Step 1 extraction (session scratchpad only)."""
import csv, io, os, subprocess

ROOT = "data/inference_test/"
SLUG = "opus-5-5"
RESULT = ROOT + f"results/{SLUG}.csv"
LOG = ROOT + f"logs/{SLUG}_log.csv"
TOKEN_COLS = "n_requests,input_tokens,cache_creation_input_tokens,cache_read_input_tokens,output_tokens,total_tokens"
COLUMNS = ["Genus", "Species", "subsp", "scientific_name", "Family",
           "fire_response categorical_surv1", "resprouter_type",
           "PJP mths", "primary_juvenile_period", "Age at first flower production from seed_repr3",
           "secondary_juvenile_period", "Time to first flower production resprout_repr3a",
           "Time to 50% flowering_repr4", "Time to 50% flowering", "Time to 80% flowering",
           "Recovery_time", "Time_unit", "Location_name", "Latitude", "Longitude", "Rainfall_mm",
           "Fire_type", "Fire_season_categorical", "Fire_severity_categorical",
           "Notes", "Source", "File_name"]
assert len(COLUMNS) == 27


def now_utc():
    return subprocess.check_output(["date", "-u", "+%FT%TZ"], text=True).strip()


def _line(cells):
    buf = io.StringIO()
    csv.writer(buf, lineterminator="\n").writerow(cells)
    return buf.getvalue()


def init():
    if not os.path.exists(RESULT):
        with open(RESULT, "w", encoding="utf-8", newline="") as f:
            f.write(_line(COLUMNS))
        with open(LOG, "w", encoding="utf-8", newline="") as f:
            f.write("paper,status,n_rows,started,finished,note," + TOKEN_COLS + "\n")


def log(paper, status, n_rows, started, finished, note):
    with open(LOG, "a", encoding="utf-8", newline="") as f:
        f.write(_line([paper, status, n_rows, started, finished, note] + [""] * 6))


def clean(v):
    return "" if v is None else str(v).strip()


def sci(genus, species, subsp):
    s = f"{clean(genus)} {clean(species)}".strip()
    return s + " *" if clean(subsp) == "*" else s


def append_rows(rows):
    """rows: list of dicts keyed by COLUMNS names."""
    with open(RESULT, "a", encoding="utf-8", newline="") as f:
        for r in rows:
            bad = set(r) - set(COLUMNS)
            assert not bad, bad
            f.write(_line([clean(r.get(c, "")) for c in COLUMNS]))
    return len(rows)


def na_row(stem, reason, source=None):
    r = {c: "NA" for c in COLUMNS}
    r["Notes"] = reason
    r["Source"] = source or stem
    r["File_name"] = stem
    return r


def remove_rows(stem):
    with open(RESULT, encoding="utf-8", newline="") as f:
        rows = list(csv.reader(f))
    keep = [rows[0]] + [r for r in rows[1:] if r[COLUMNS.index("File_name")] != stem]
    n = len(rows) - len(keep)
    if n:
        with open(RESULT, "w", encoding="utf-8", newline="") as f:
            for r in keep:
                f.write(_line(r))
    return n


def pages(path):
    txt = open(path, encoding="utf-8").read()
    return txt.split("<!-- PAGE BREAK -->")

