import re, random, sys
sys.path.insert(0, __file__.rsplit("/", 1)[0])
import pipe

STEM = "Knox & Clarke 2004 Cunninghamia_primary juvenile period"
PATH = f"data/papers_test/md_agents/{STEM}.md"
SRC = ("Knox, K.J.E. & Clarke, P.J. (2004). Fire response syndromes of shrubs in grassy woodlands in the "
       "New England Tableland Bioregion. Cunninghamia 8(3): 348–353.")
txt = open(PATH, encoding="utf-8").read()


def table(after):
    i = txt.index(after)
    rows = []
    for ln in txt[i:].splitlines():
        if ln.startswith("|"):
            rows.append([c.strip() for c in ln.strip().strip("|").split("|")])
        elif rows:
            break
    return rows[2:]


def name(s):
    s = s.replace("*", "").strip()
    m = re.fullmatch(r"(\S+) (.+?)(?: (subsp\.|var\.) (\S+))?", s)
    return m.group(1), m.group(2), m.group(4) or "", m.group(3) or ""


t1 = {name(r[0])[:3]: r for r in table("| Species | Fire response | Survival %")}
t2 = table("| Species | Fire response | Primary juvenile period")
CODE = {"resprouter": "resprouter", "obligate seeder": "obligate"}


def tval(v):
    v = v.replace("\\*", "").strip()
    if v in ("", "n.a."):
        return ""
    m = re.fullmatch(r"Not flowering after ([\d.]+) years", v)
    if m:
        return ">" + m.group(1)
    m = re.fullmatch(r"(<|>)?\s*([\d.]+) years", v)
    return (m.group(1) or "") + m.group(2)


rows = []
for sp_txt, resp, pjp, sjp in t2:
    g, sp, ssp, rank = name(sp_txt)
    r = dict(Genus=g, Species=sp, subsp=ssp, scientific_name=pipe.sci(g, sp, ""),
             **{"fire_response categorical_surv1": CODE[resp]},
             primary_juvenile_period=tval(pjp), secondary_juvenile_period=tval(sjp),
             Location_name="Imbota Nature Reserve / Booroolong Nature Reserve",
             Fire_type="experimental burn", Fire_season_categorical="Autumn/Spring",
             Source=SRC, File_name=STEM)
    if r["secondary_juvenile_period"]:
        r["Time_unit"] = "years"
    notes = ["Table 2 (p. 351) and Table 1 (p. 350) pool both reserves; site of each species not stated",
             "fires: experimental burns at Imbota NR in Spring 1999 and Booroolong NR in Autumn 2000",
             "rainfall: Imbota (Armidale) 790 mm, Booroolong (Guyra, similar climate) 884 mm average yearly",
             "fire intensity not measured; authors expected low (low fuel load) and moderate (high fuel load) "
             "intensity fires"]
    if rank == "var.":
        notes.append(f"subsp column holds variety name (var. {ssp})")
    k = (g, sp, ssp)
    if k in t1:
        _, _, surv, n, mode = t1[k]
        if mode != "n.a.":
            r["resprouter_type"] = mode
        notes.append(f"survival {surv}% {n} after 100% leaf scorch (Table 1); obligate seeder <30% survival, "
                     f"resprouter >70%")
    else:
        notes.append("not in Table 1; fire response from Table 2")
    if "\\*" in pjp:
        notes.append("primary juvenile period: no data (*)")
    if "\\*" in sjp:
        notes.append("secondary juvenile period: no data (*)")
    if r["primary_juvenile_period"]:
        notes.append("primary juvenile period data from naturally recruiting populations and field-sown seed")
    if k == ("Indigofera", "australis", ""):
        notes.append("Discussion says primary juvenile period 'appears to be more than four years' in this study; "
                     "Wark (1997) gives 2 years in Victoria (literature)")
    if k == ("Hardenbergia", "violacea", ""):
        notes.append("Benson & McDougall (1996) give primary juvenile period one year in Sydney Region (literature)")
    if k == ("Acacia", "filicifolia", ""):
        notes.append("Discussion: secondary juvenile period greater than 4 years")
    r["Notes"] = "; ".join(notes)
    rows.append(r)

if __name__ == "__main__":
    random.seed(2)
    for r in random.sample(rows, 3):
        print({c: r[c] for c in ("scientific_name", "subsp", "fire_response categorical_surv1",
                                 "primary_juvenile_period", "secondary_juvenile_period")}, r.get("resprouter_type"))
        for ln in txt.splitlines():
            if ln.startswith("| *" + r["Genus"] + "* " ) and r["Species"] in ln:
                print("   ", ln)
    print(len(rows), "rows")
    if "--write" in sys.argv:
        print("appended", pipe.append_rows(rows))

