def rows_for_pages(first, last):
    out, skipped = [], []
    for pi in range(first - 1, last):
        page_no = FIRST_PAGE + pi
        for ln in PAGES[pi].splitlines():
            if not ln.startswith("|") or set(ln) <= set("|-: "):
                continue
            c = [x.strip() for x in ln.strip().strip("|").split("|")]
