        if cell and not ("<u>" in cell and label == "First fruiting Seed"):
            snotes.append(f"{label}: {cell.replace('<u>', '').replace('</u>', '')}"
                          + (" (underlined: unclear whether from seed or resprouts)" if "<u>" in cell else ""))
    if pjp:
        p = parse_time(pjp)
        if p:
            val, unit, q = p
            shared["primary_juvenile_period"] = to_years(val, unit)
            n = f"Primary juvenile period printed '{pjp}'"
            if unit == "weeks":
                n += f"; primary_juvenile_period converted from {val} weeks"
            if q:
                n += f" ({q})"
            snotes.append(n)
        else:
            snotes.append(f"Primary juvenile period: {pjp}")
    if sjp:
        p = parse_time(sjp)
        if p:
            val, unit, q = p
            shared["secondary_juvenile_period"] = val
            shared["Time_unit"] = unit
            n = f"Secondary juvenile period printed '{sjp}'"
            if q:
                n += f" ({q})"
            snotes.append(n)
        else:
            snotes.append(f"Secondary juvenile period: {sjp}")
    if seedl:
        snotes.append(f"Seedlings first observed: {seedl}")
    if peaks:
        snotes.append(f"post-fire peaks: {peaks}")
    if any(k in " ".join(snotes) for k in ("shd", "grn", "ri", "fruit")):
        snotes.append("abbreviations: grn. = green fruit, imm. = immature fruit, ri. = ripe fruit, "
                      "(shd) = shedding seed or spores; w = weeks, y = years")

    l_code, l_note = code_cell(lcr)
    n_code, n_note = code_cell(nl)
    common = [f"Appendix 1 p. {page_no}"] + nnotes
    code_def = ("codes: R = majority of adults resprouted, K = majority killed, r/k = small proportion "
                "resprouted/killed, p = probably (80–90% sure), ? = possibly (50–70% sure)")
    rows = []

    def mk(loc, code, extra, times, site):
        r = dict(base, **loc)
        if code:
            r["fire_response categorical_surv1"] = code
        if times:
            r.update(shared)
        notes = list(common)
        if site == "LCR":
            notes.append("site Lane Cove River (LCR) valley, coordinates from Methods; observations mainly Jan 1994 – Oct 1999")
        elif site == "NL":
            notes.append("site Narrabeen Lagoon (NL) catchment, no coordinates given; observations Mar – Oct 1994")
        else:
            notes.append("time values in Appendix 1 are not split by catchment (LCR and NL)")
        if code:
            notes.append(f"fire response code printed '{lcr if site == 'LCR' else nl}'; {code_def}")
        notes += [x for x in extra if x]
        if times:
            notes += snotes
        key = (f"{genus} {sp}", site)
        if key in TEXT:
            notes.append(TEXT[key])
        notes.append(FIRE_NOTE)
        r["Notes"] = "; ".join(notes)
        rows.append(r)

    has_times = bool(shared)
    both = bool(l_code) and bool(n_code)
    if l_code:
        mk(LCR_LOC, l_code, [l_note, n_note if not n_code else ""], has_times and not both, "LCR")
    if n_code:
        mk(NL_LOC, n_code, [n_note, l_note if not l_code else ""], has_times and not both, "NL")
    if has_times and (both or not (l_code or n_code)):
        extra = [] if both else ["no fire response code printed for either catchment; site of observation not stated",
                                 l_note, n_note]
        mk(JOINT_LOC, "", extra, True, "joint")
    if not rows:
        return [], f"{name} (p. {page_no}): no fire response code and no time value"
    # carry notes of species with no row-making values but with notes into an existing row
    if not has_times and snotes:
        rows[0]["Notes"] += "; " + "; ".join(snotes)
    return rows, None


if __name__ == "__main__":
    first, last = int(sys.argv[1]), int(sys.argv[2])
    rows, skipped = rows_for_pages(first, last)
    print(len(rows), "rows;", len(skipped), "skipped:", skipped)
    if "--sample" in sys.argv:
        random.seed(first)
        for r in random.sample(rows, 3):
            print({k: v for k, v in r.items() if v and k not in ("Source", "File_name")})
            for ln in "\n".join(PAGES[first - 1:last]).splitlines():
                if f"| {r['Genus']} {r['Species']}" in ln or f"| *{r['Genus']} {r['Species']}" in ln:
                    print("   SRC", ln)
    if "--write" in sys.argv:
        print("appended", pipe.append_rows(rows))

