import re, random, sys
sys.path.insert(0, __file__.rsplit("/", 1)[0])
import pipe

STEM = "Kubiak Cunn 2009"
PATH = f"data/papers_test/md_agents/{STEM}.md"
SRC = ("Kubiak, P.J. (2009). Fire responses of bushland plants after the January 1994 wildfires in northern "
       "Sydney. Cunninghamia 11(1): 131–165.")
PAGES = pipe.pages(PATH)
FIRST_PAGE = 131  # printed page number of PDF page 1

LCR_LOC = dict(Latitude="-33.75", Longitude="151.0833")
NL_LOC = dict(Location_name="Narrabeen Lagoon catchment area")
JOINT_LOC = dict(Location_name="Lane Cove River valley / Narrabeen Lagoon catchment area")
FIRE = dict(Fire_type="wildfire", Fire_season_categorical="Summer", Fire_severity_categorical="High")
FIRE_NOTE = ("fire: January 1994 wildfires, season Summer derived from fire date; severity: fires 'generally "
             "described as being of a very high intensity', patchy with some low or moderate intensity patches; "
             "all fire responses for plants with 100% leaf scorch; rainfall not stated")
CODE = {"R": "resprouter", "K": "obligate"}

# Site-specific statements from the paper text (pages 1-10), placed in Notes of the matching site row.
TEXT = {
    ("Xanthorrhoea media", "LCR"): "text p. 137: in LCR flowered 39–43 weeks, fruits c. 49 weeks, shedding seed 56–63 weeks after the fires",
    ("Xanthorrhoea media", "NL"): "text p. 137: in NL flowered 17–21 weeks after the fires",
    ("Xanthorrhoea arborea", "LCR"): "text p. 137: in LCR flowered 51–56 weeks, fruit at 63 weeks, seed release c. 100 weeks after the fires",
    ("Xanthorrhoea arborea", "NL"): "text p. 137: in NL flowered 35–38 weeks after the fires",
    ("Leptospermum trinervium", "NL"): "text p. 138: one plant in NL flowering 17 weeks (May 1994) after the fires",
    ("Hakea dactyloides", "LCR"): "text p. 138: in LCR took approximately 6.5 years to produce a few fruits",
    ("Persoonia lanceolata", "LCR"): "text p. 138: at one LCR site a few seedlings flowered for the first time in January 1996; no fruits by June 1996",
    ("Podocarpus spinulosus", "LCR"): "text p. 136: in LCR resprouts first flowered October 1995, some mature fruit by early December 1995 (c. 100 weeks)",
    ("Brunoniella pumilio", "LCR"): "text p. 138: in LCR flowered within 6 weeks and fruited within 11 weeks",
    ("Gahnia clarkei", "LCR"): "text p. 137: in LCR took approximately 3 years (January 1997) to produce fruits",
    ("Chrysanthemoides monilifera", "LCR"): "text p. 140: in LCR seedlings observed 19 weeks after the fires, flowered September 1995, mature fruits by December 1995",
    ("Rorippa gigantea", "NL"): "text p. 139: seen flowering and beginning to form fruit along Deep Creek (NL) within 38 weeks",
    ("Callitris muelleri", "NL"): "text p. 136: killed in NL; seedlings within 32 weeks near fatally scorched adults",
    ("Lobelia dentata", "LCR"): "text pp. 138, 141: in LCR no flowering plants within approximately 2–3 years; author unsure whether post-fire plants were seedlings or resprouts",
    ("Persoonia pinifolia", "LCR"): "text p. 139: post-fire seedlings first observed 124 weeks (May 1996) after the fires in LCR",
    ("Lomatia silaifolia", "LCR"): "text p. 138: in LCR many individuals flowered December 1994 to January 1995",
    ("Muellerina eucalyptoides", "LCR"): "text p. 136: resprouted after an evidently low to moderate intensity fire",
    ("Pelargonium inodorum", "LCR"): "text p. 138-139: in LCR apparently disappeared by about 2 years after the fires",
    ("Gompholobium latifolium", "LCR"): "text p. 137: killed in LCR, scattered plants resprouted in NL",
    ("Acacia oxycedrus", "LCR"): "text p. 137: killed in LCR, mostly resprouted in NL",
    ("Xanthosia pilosa", "LCR"): "text p. 138: mostly killed in LCR, some plants resprouted",
    ("Astrotricha longifolia", "LCR"): "text p. 138: probably mostly killed in LCR, a few scattered plants resprouted",
}


def fmt(x):
    s = f"{x:.3f}".rstrip("0").rstrip(".")
    return s


def parse_time(cell):
    """Return (value, unit, note) for the first time value in a cell, or None.
    value keeps printed decimals; unit 'weeks' or 'years'."""
    raw = cell
    s = re.sub(r"</?u>", "", cell).strip()
    m = re.fullmatch(r"Less than (\d+(?:\.\d+)?) years?", s)
    if m:
        return "<" + m.group(1), "years", ""
    m = re.fullmatch(r"At least (\d+(?:\.\d+)?) years?", s)
    if m:
        return ">" + m.group(1), "years", "printed 'At least %s years'" % m.group(1)
    s2 = s.replace("**", "")
    m = re.match(r"^(\?)?\s*(c\.)?\s*(\?)?\s*(\d+(?:\.\d+)?)\s*(?:[–-]\s*(\d+(?:\.\d+)?))?(\+)?\s*([wy])?(.*)$", s2)
    if not m:
        return None
    q1, approx, q2, a, b, plus, unit, rest = m.groups()
    if unit is None:
        # unit printed only on a later value of the cell, e.g. "40,**52w**" or "2 & 3w"
        mu = re.search(r"\d\s*([wy])", rest)
        if not mu or not re.match(r"^\s*(,|&)", rest):
            return None
        unit = mu.group(1)
        unit_borrowed = True
    else:
        unit_borrowed = False
    val = a if not b else f"{a}-{b}"
    if plus:
        val = ">" + val
    notes = []
    if approx:
        notes.append("printed with 'c.' (approximately)")
    if q1 or q2 or "?" in rest:
        notes.append("printed with '?'")
    if plus:
        notes.append(f"printed as {a}+ (i.e. {a} or more)")
    if unit_borrowed:
        notes.append("unit taken from the next value in the cell")
    if "**" in s:
        notes.append("bold value = sizable proportion of population flowering")
    return val, {"w": "weeks", "y": "years"}[unit], "; ".join(notes)


def to_years(val, unit):
    if unit == "years":
        return val
    pre = val[0] if val[0] in "<>" else ""
    parts = val.lstrip("<>").split("-")
    return pre + "-".join(fmt(float(p) / 52) for p in parts)


def split_name(s):
    exotic, notes = "", []
    if s.startswith("(*?)"):
        notes.append("printed with '(*?)': possibly exotic, not marked as introduced")
        s = s[4:]
    elif s.startswith("*"):
        exotic = "*"
        s = s[1:]
    for q in ("(s.lat.)", "(s.str.)"):
        if q in s:
            notes.append(f"name printed with {q}")
            s = s.replace(q, "").strip()
    m = re.search(r"\s*\(syn\. ([^)]*)\)", s)
    if m:
        notes.append(f"printed with (syn. {m.group(1)})")
        s = s[:m.start()] + s[m.end():]
    genus, rest = s.split(" ", 1)
    infra = ""
    m = re.search(r" (var\.|subsp\.|cv\.) (.+)$", rest)
    if m:
        infra = m.group(2)
        rest = rest[:m.start()]
        if m.group(1) == "var.":
            notes.append(f"variety: var. {infra}")
        if m.group(1) == "cv.":
            notes.append(f"cultivar: cv. {infra}")
            infra = ""
    if exotic:
        if infra:
            notes.append(f"infraspecific name {infra} (subsp column holds '*' for exotic species)")
        infra = "*"
    return genus, rest.strip(), infra, notes


def code_cell(v):
    """Fire response code: R/K -> resprouter/obligate, anything else copied as printed."""
    if not v:
        return "", ""
    if v.startswith("The host") or v.startswith("One plant"):
        return "", f"fire response cell text: {v}"
    m = re.match(r"^(R\(1\)m\.i\.f)\s+(.*)$", v)
    if m:
        return m.group(1), f"fire response cell: {v}; R(1)m.i.f = one plant resprouted after moderate intensity fire"
    if v in CODE:
        return CODE[v], ""
    return v, ""


def rows_for_pages(first, last):
    out, skipped = [], []
    for pi in range(first - 1, last):
        page_no = FIRST_PAGE + pi
        for ln in PAGES[pi].splitlines():
            if not ln.startswith("|") or set(ln) <= set("|-: "):
                continue
            c = [x.strip() for x in ln.strip().strip("|").split("|")]
            if c[0] == "Family":
                continue
            out_rows, sk = species_rows(c, page_no)
            out += out_rows
            if sk:
                skipped.append(sk)
    return out, skipped


