            continue
        p = parse_time(cell)
        if p is None:
            snotes.append(f"{label}: {cell}")
            continue
        val, unit, q = p
        shared[col] = to_years(val, unit)
        n = f"{label} printed '{cell}'"
        if unit == "weeks":
            n += f"; {col} converted from {val} weeks"
        if q:
            n += f" ({q})"
        snotes.append(n)
    for cell, label in ((frr, "First fruiting Resp"), (frs, "First fruiting Seed")):
