            snotes.append(f"{label}: {cell.replace('<u>', '').replace('</u>', '')}"
                          + (" (underlined: unclear whether from seed or resprouts)" if "<u>" in cell else ""))
    if pjp:
        p = parse_time(pjp)
        if p:
            val, unit, q = p
