            if q:
                n += f" ({q})"
            snotes.append(n)
        else:
            snotes.append(f"Primary juvenile period: {pjp}")
    if sjp:
        p = parse_time(sjp)
        if p:
            val, unit, q = p
            shared["secondary_juvenile_period"] = val
            shared["Time_unit"] = unit
            n = f"Secondary juvenile period printed '{sjp}'"
