    if peaks:
        snotes.append(f"post-fire peaks: {peaks}")
    if any(k in " ".join(snotes) for k in ("shd", "grn", "ri", "fruit")):
        snotes.append("abbreviations: grn. = green fruit, imm. = immature fruit, ri. = ripe fruit, "
                      "(shd) = shedding seed or spores; w = weeks, y = years")

    l_code, l_note = code_cell(lcr)
    n_code, n_note = code_cell(nl)
    common = [f"Appendix 1 p. {page_no}"] + nnotes
    code_def = ("codes: R = majority of adults resprouted, K = majority killed, r/k = small proportion "
                "resprouted/killed, p = probably (80–90% sure), ? = possibly (50–70% sure)")
    rows = []

    def mk(loc, code, extra, times, site):
        r = dict(base, **loc)
        if code:
            r["fire_response categorical_surv1"] = code
        if times:
            r.update(shared)
        notes = list(common)
        if site == "LCR":
            notes.append("site Lane Cove River (LCR) valley, coordinates from Methods; observations mainly Jan 1994 – Oct 1999")
        elif site == "NL":
            notes.append("site Narrabeen Lagoon (NL) catchment, no coordinates given; observations Mar – Oct 1994")
        else:
            notes.append("time values in Appendix 1 are not split by catchment (LCR and NL)")
        if code:
            notes.append(f"fire response code printed '{lcr if site == 'LCR' else nl}'; {code_def}")
        notes += [x for x in extra if x]
        if times:
            notes += snotes
        key = (f"{genus} {sp}", site)
        if key in TEXT:
