    if has_times and (both or not (l_code or n_code)):
        extra = [] if both else ["no fire response code printed for either catchment; site of observation not stated",
                                 l_note, n_note]
        mk(JOINT_LOC, "", extra, True, "joint")
    if not rows:
        return [], f"{name} (p. {page_no}): no fire response code and no time value"
    # carry notes of species with no row-making values but with notes into an existing row
    if not has_times and snotes:
        rows[0]["Notes"] += "; " + "; ".join(snotes)
    return rows, None


if __name__ == "__main__":
    first, last = int(sys.argv[1]), int(sys.argv[2])
    rows, skipped = rows_for_pages(first, last)
    print(len(rows), "rows;", len(skipped), "skipped:", skipped)
    if "--sample" in sys.argv:
        random.seed(first)
        for r in random.sample(rows, 3):
