import re, random, sys
sys.path.insert(0, __file__.rsplit("/", 1)[0])
import pipe

STEM = "nswfrrd_v1.3a_pdfvers_sppdata"
PAGES = pipe.pages(f"data/papers_test/md_agents/{STEM}.md")


def tab(t):
    rows = [[x.strip() for x in l.strip().strip("|").split("|")] for l in t.splitlines() if l.startswith("|")]
    return rows[2:]


def split_name(s):
    m = re.fullmatch(r"(\S+) (.+?)(?: (subsp\.|var\.|f\.) (.+))?", s)
    return m.group(1), m.group(2), m.group(4) or "", m.group(3) or ""


def rows_for(first, last):
    out = []
    for i in range(first - 1, last, 2):  # even PDF page (regeneration) + following odd page (vital attributes)
        if i + 1 >= last:
            raise ValueError("batch must hold whole page pairs")
        for a, b in zip(tab(PAGES[i]), tab(PAGES[i + 1])):
            sp, syn, fam, fr, comm, store, disp, germ, nfrr, addl = a
            sp2, va, sfreq, sinf, pjp, sjp, rmi, life, cons, dist, veg, flow = b
            assert sp == sp2, (sp, sp2)
            genus, species, infra, rank = split_name(sp)
            exotic = dist.strip() == "Exotic"
            notes = [f"PDF pages {i + 1}-{i + 2}",
                     f"fire response code '{fr}' copied as printed; codes not defined in this document"]
            if rank in ("var.", "f."):
                notes.append(f"subsp column holds {rank} {infra}")
            if exotic:
                notes.append("Distribution: NSW printed as 'Exotic'"
                             + (f"; infraspecific name {rank} {infra}" if infra else ""))
                infra = "*"
            if syn:
                notes.append(f"synonym: {syn}")
            if comm:
                notes.append(f"comments on regeneration: {comm}")
            if pjp:
                notes.append(f"Primary juvenile: {pjp} (unit not stated)")
            if sjp:
                notes.append(f"Secondary juvenile period: {sjp} (unit not stated)")
            if rmi:
                notes.append(f"Recommended minimum interval: {rmi} (unit not stated)")
            notes.append("database printout: no study site, fire or citation printed")
            out.append(dict(Genus=genus, Species=species, subsp=infra,
                            scientific_name=pipe.sci(genus, species, infra), Family=fam,
                            **{"fire_response categorical_surv1": fr}, Notes="; ".join(notes),
                            Source=STEM, File_name=STEM))
    return out


if __name__ == "__main__":
    first, last = int(sys.argv[1]), int(sys.argv[2])
    rows = rows_for(first, last)
    print(f"pages {first}-{last}: {len(rows)} rows")
    if "--sample" in sys.argv:
        random.seed(first)
        for r in random.sample(rows, 3):
            print("  ", r["scientific_name"], "|", r["subsp"], "|", r["Family"], "|", r["fire_response categorical_surv1"], "|", r["Notes"][:250])
            for l in "\n".join(PAGES[first - 1:last]).splitlines():
                name = r["Genus"] + " " + r["Species"]
                if l.startswith(f"| {name} ") and (r["subsp"] in ("", "*") or r["subsp"] in l):
                    print("     SRC", l[:250])
    if "--write" in sys.argv:
        print("appended", pipe.append_rows(rows))

